    vector<int> a = {4, 2, 12, 3, 8, 1};
    int k = 3;
    multiset<int> okno;
    for (int i = 0; i < (int)a.size(); i++) {
        okno.insert(a[i]);
        if (i >= k) okno.erase(okno.find(a[i - k]));   // usuń dokładnie jedną kopię
